        """Initializes MultiframeWrapper

        Parameters
        ----------
        dcm_data : object
           object should allow 'get' and '__getitem__' access.  Usually this
           will be a ``dicom.dataset.Dataset`` object resulting from reading a
           DICOM file, but a dictionary should also work.
        """
        Wrapper.__init__(self, dcm_data)
        self.dcm_data = dcm_data
        self.frames = dcm_data.get('PerFrameFunctionalGroupsSequence')
        try:
            self.frames[0]
        except (TypeError, IndexError):
            raise WrapperError('PerFrameFunctionalGroupsSequence is empty.')
        try:
            self.shared = dcm_data.get('SharedFunctionalGroupsSequence')[0]
        except (TypeError, IndexError):
            raise WrapperError('SharedFunctionalGroupsSequence is empty.')
        if len(self.frames) != self.get('NumberOfFrames'):
            raise WrapperError('NumberOfFrames does not match the per-frame functional groups.')

        # Keep the original pixel frame numbers when removing derived DWI images.
        # Geometry, dimension indices and scaling must use the same selection.
        self._frame_numbers = np.arange(len(self.frames))
        self._has_derived = False
        diffusion = [self._get_frame_sequence(frame, 'MRDiffusionSequence') for frame in self.frames]
        if all(item is not None and item.get('DiffusionDirectionality') for item in diffusion):
            keep = [item.DiffusionDirectionality != 'ISOTROPIC' for item in diffusion]
            if any(keep) and not all(keep):
                self._frame_numbers = self._frame_numbers[keep]
                self.frames = [self.frames[i] for i in self._frame_numbers]
                self._has_derived = True
                warnings.warn('Derived images found and removed')

    def _get_frame_sequence(self, frame, name):
        """Get a functional group macro, whether shared or per-frame."""
        sequence = frame.get(name, self.shared.get(name))
        return sequence[0] if sequence else None

    @cached_property
    def image_shape(self):
        """The array shape as it will be returned by ``get_data()``

        The shape is determined by the *Rows* DICOM attribute, *Columns*
        DICOM attribute, and the set of frame indices given by the
        *FrameContentSequence[0].DimensionIndexValues* DICOM attribute of each
        element in the *PerFrameFunctionalGroupsSequence*.  The first two
        axes of the returned shape correspond to the rows, and columns
        respectively. The third axis contains slices in increasing order along
        ``slice_normal``, determined from their patient positions. The remaining
        axes correspond to non-spatial frame indices with order preserved.

        What each axis in the frame indices refers to is given by the
        corresponding entry in the *DimensionIndexSequence* DICOM attribute.
        **WARNING**: Any axis referring to the *StackID* DICOM attribute will
        have been removed from the frame indices in determining the shape. This
        is because only a file containing a single stack is currently allowed by
        this wrapper.

        References
        ----------
        * C.7.6.16 Multi-Frame Functional Groups Module:
          http://dicom.nema.org/medical/dicom/current/output/pdf/part03.pdf#sect_C.7.6.16
        * C.7.6.17 Multi-Frame Dimension Module:
          http://dicom.nema.org/medical/dicom/current/output/pdf/part03.pdf#sect_C.7.6.17
        * Diagram of DimensionIndexSequence and DimensionIndexValues:
          http://dicom.nema.org/medical/dicom/current/output/pdf/part03.pdf#figure_C.7.6.17-1
        """
        rows, cols = self.get('Rows'), self.get('Columns')
        if None in (rows, cols):
            raise WrapperError('Rows and/or Columns are empty.')

        n_frames = len(self.frames)
        shape = (rows, cols) + tuple(len(np.unique(row)) for row in self._frame_indices.T)
        n_vols = np.prod(shape[3:], dtype=int)
        n_frames_calc = n_vols * shape[2]
        if n_frames != n_frames_calc:
            raise WrapperError(
                f'Calculated # of frames ({n_frames_calc}={n_vols}*{shape[2]}) '
                f'of shape {shape} does not match NumberOfFrames {n_frames}.'
            )
        return shape

    @cached_property
    def _frame_indices(self):
        contents = [self._get_frame_sequence(frame, 'FrameContentSequence') for frame in self.frames]
        if any(content is None for content in contents):
            raise WrapperError('Not enough information for frame indices')
        # Check that there is only one multiframe stack index
        stack_ids = {content.get('StackID') for content in contents}
        if len(stack_ids) > 1:
            raise WrapperError(
                'File contains more than one StackID. Cannot handle multi-stack files'
            )
        dim_seq = [dim.DimensionIndexPointer for dim in self.get('DimensionIndexSequence')]
        # pydicom returns a scalar for a single DimensionIndexValues entry.
        try:
            frame_indices = np.array(
                [np.atleast_1d(content.DimensionIndexValues) for content in contents], dtype=int
            )
        except (AttributeError, ValueError):
            raise WrapperError('Not enough information for frame indices')
        if frame_indices.shape != (len(self.frames), len(dim_seq)):
            raise WrapperError('DimensionIndexValues does not match DimensionIndexSequence')

        stackid_tag = pydicom.datadict.tag_for_keyword('StackID')
        spatial_tags = {
            pydicom.datadict.tag_for_keyword(keyword)
            for keyword in ('InStackPositionNumber', 'ImagePositionPatient', 'PlanePositionSequence')
        }
        non_spatial = [
            i for i, tag in enumerate(dim_seq) if tag != stackid_tag and tag not in spatial_tags
        ]
        # Dimension indices are logical ordinals, not spatial coordinates. The
        # slice dimension can occur anywhere in the sequence, and its values
        # need not increase along the slice normal (PS3.3 C.7.6.17.1).
        slice_indices = self._slice_geometry[1]
        frame_indices = np.column_stack((slice_indices, frame_indices[:, non_spatial]))
        if self._has_derived:
            # Philips may index b-value redundantly with diffusion direction.
            # Drop it only if the remaining indices still form a complete grid.
            bvalue_tag = pydicom.datadict.tag_for_keyword('DiffusionBValue')
            remaining_tags = [dim_seq[i] for i in non_spatial]
            if bvalue_tag in remaining_tags:
                candidate = np.delete(frame_indices, remaining_tags.index(bvalue_tag) + 1, axis=1)
                n_unique = len(np.unique(candidate, axis=0))
                grid_size = np.prod([len(np.unique(row)) for row in candidate.T])
                if n_unique == grid_size == len(self.frames):
                    frame_indices = candidate
        if len(np.unique(frame_indices, axis=0)) != len(self.frames):
            raise WrapperError('Frame indices do not uniquely identify frames')
        return frame_indices

    @cached_property
    def _frame_order(self):
        # First array index changes fastest, last slowest, for the F reshape.
        return np.lexsort(self._frame_indices.T)

    @cached_property
    def image_orient_patient(self):
        """
        Note that this is _not_ LR flipped
        """
        orientations = []
        for frame in self.frames:
            orient = self._get_frame_sequence(frame, 'PlaneOrientationSequence')
            if orient is None or orient.get('ImageOrientationPatient') is None:
                raise WrapperError('Not enough information for image_orient_patient')
            orientations.append(orient.ImageOrientationPatient)
        orientations = np.asarray(orientations, dtype=float)
        if not np.allclose(orientations, orientations[0], rtol=0, atol=5e-5):
            raise WrapperError('Frames have different image orientations')
        return orientations[0].reshape(2, 3).T

    @cached_property
    def _slice_geometry(self):
        """Physical slice positions, each frame's slice index, and slice step."""
        positions = []
        for frame in self.frames:
            plane = self._get_frame_sequence(frame, 'PlanePositionSequence')
            if plane is None or plane.get('ImagePositionPatient') is None:
                raise WrapperError('Cannot get image position from dicom')
            positions.append(plane.ImagePositionPatient)
        positions = np.asarray(positions, dtype=float)
        if positions.shape != (len(self.frames), 3) or not np.all(np.isfinite(positions)):
            raise WrapperError('Invalid image positions')
        normal = self.slice_normal
        normal = normal / np.linalg.norm(normal)
        distances = positions @ normal
        order = np.argsort(distances, kind='stable')
        # Allow small DS rounding differences between nominally equal planes.
        new_slice = np.r_[True, np.diff(distances[order]) > 1e-4]
        slice_indices = np.empty(len(self.frames), dtype=int)
        slice_indices[order] = np.cumsum(new_slice) - 1
        slice_positions = positions[order[new_slice]]
        if not np.allclose(positions, slice_positions[slice_indices], rtol=0, atol=1e-4):
            raise WrapperError('Frames at the same slice have different image positions')
        step = None
        if len(slice_positions) > 1:
            step = (slice_positions[-1] - slice_positions[0]) / (len(slice_positions) - 1)
            expected = slice_positions[0] + np.arange(len(slice_positions))[:, None] * step
            if not np.allclose(slice_positions, expected, rtol=0, atol=1e-4):
                raise WrapperError('Slice positions are not regularly spaced')
            if not np.allclose(step / np.linalg.norm(step), normal, rtol=0, atol=5e-5):
                raise WrapperError('Slice positions do not lie along the slice normal')
        return slice_positions, slice_indices, step

    @cached_property
    def rotation_matrix(self):
        rotation = super().rotation_matrix
        step = self._slice_geometry[2]
        if step is not None:
            # Use the measured displacement so rounding of direction cosines
            # does not accumulate into an error at the far end of the volume.
            rotation[:, 2] = step / np.linalg.norm(step)
        return rotation

    @cached_property
    def voxel_sizes(self):
        """Get i, j, k voxel sizes"""
        measures = [self._get_frame_sequence(frame, 'PixelMeasuresSequence') for frame in self.frames]
        for item in measures:
            if item is None or item.get('PixelSpacing') is None:
                raise WrapperError('Not enough data for pixel spacing')
        pixel_spacing = np.asarray([item.PixelSpacing for item in measures], dtype=float)
        if not np.allclose(pixel_spacing, pixel_spacing[0]):
            raise WrapperError('Frames have different pixel spacing')
        step = self._slice_geometry[2]
        if step is not None:
            zs = np.linalg.norm(step)
        else:
            # Thickness describes the excited slab, not center-to-center
            # spacing. Use it only when there are no distinct slice positions
            # or spacing metadata from which to determine a slice step.
            zs = measures[0].get('SpacingBetweenSlices', self.get('SpacingBetweenSlices'))
            if zs is None or zs == '':
                zs = measures[0].get('SliceThickness')
            if zs is None or zs == '':
                raise WrapperError('Not enough data for slice thickness')
        return (*map(float, pixel_spacing[0]), float(zs))

    @cached_property
    def image_position(self):
        return self._slice_geometry[0][0]

    @cached_property
    def series_signature(self):
        signature = {}
        eq = operator.eq
        for key in ('SeriesInstanceUID', 'SeriesNumber', 'ImageType'):
            signature[key] = (self.get(key), eq)
        signature['image_shape'] = (self.image_shape, eq)
        signature['iop'] = (self.image_orient_patient, none_or_close)
        signature['vox'] = (self.voxel_sizes, none_or_close)
        return signature

    def get_data(self):
        shape = self.image_shape
        if shape is None:
            raise WrapperError('No valid information for image shape')
        data = np.asarray(self.get_pixel_array())
        # pydicom omits the frames axis for a single-frame object.
        if data.ndim == 2:
            data = data[None, ...]
        if data.shape != (self.get('NumberOfFrames'), *shape[:2]):
            raise WrapperError('Pixel array shape does not match the frame metadata')
        data = data[self._frame_numbers[self._frame_order]]
        # Roll frames axis to last
        data = data.transpose((1, 2, 0))
        data = data.reshape(shape, order='F')
        return self._scale_data(data)

    def _scale_data(self, data):
        factors = []
        for frame in self.frames:
            transform = self._get_frame_sequence(frame, 'PixelValueTransformationSequence')
            if transform is None:
                transform = self.dcm_data
            factors.append((float(transform.get('RescaleSlope', 1)),
                            float(transform.get('RescaleIntercept', 0))))
        factors = np.asarray(factors)
        if np.all(factors == factors[0]):
            return self._apply_scale_offset(data, *factors[0])
        scale, offset = factors[self._frame_order].T
        scale = scale.reshape(self.image_shape[2:], order='F')
        offset = offset.reshape(self.image_shape[2:], order='F')
        return data * scale + offset


